export function installUpgrade(api){
 const {esc,uid,dayKey,photo,showDialog,save,toast}=api;
 const $=(s,r=document)=>r.querySelector(s), s=()=>api.state();
 const choices=['Confidence','Health','Consistency','Freedom','Connection','Kindness','Growth','Curiosity','Creativity','Independence','Balance','Adventure','Self-respect','Security'];
 const categories=['Personal','Fitness','Learning','Career','Travel','Wellbeing','Movement','Home','Connection','Relationships','Hygiene','Money','Creativity'];
 const people=[{id:'alex',name:'Alex Rivera',handle:'alexinmotion',bio:'Building strength and showing up for myself.',values:['Confidence','Consistency'],plan:'demo-strength',image:'gym'},{id:'jules',name:'Jules Park',handle:'julesgetsgoing',bio:'More focus. More curiosity. More finished projects.',values:['Curiosity','Growth'],plan:'demo-focus',image:'study'},{id:'sam',name:'Sam Taylor',handle:'samtakesoff',bio:'Making room for new places and experiences.',values:['Freedom','Adventure'],plan:'demo-trip',image:'travel'}];
 const sampleAffirmations=[{id:'affirm-alex',owner:'alex',author:'Alex Rivera',name:'Strong in every season',affirmations:['My strength grows every time I show up.','I listen to my body and honor its needs.','I belong in every room I enter.']},{id:'affirm-jules',owner:'jules',author:'Jules Park',name:'Focused and becoming',affirmations:['My attention is sacred.','I finish what matters to me.','Curiosity guides me forward.']},{id:'affirm-sam',owner:'sam',author:'Sam Taylor',name:'Open roads',affirmations:['The world welcomes me.','I make room for wonder.','I trust myself in unfamiliar places.']}];
 let search='',filterValue='',filterCategory='',friendsOnly=false,exploreTab='search',exploreTypes=['plans','affirmations','boards','images'],selectedCategories=[],selectedValues=[];
function init(){const st=s();st.community??={name:'Your name',bio:'Building my next chapter.',following:[],updates:[],reviews:[]};st.community.following??=[];st.community.followers??=['alex','sam'];st.community.updates??=[];st.community.reviews??=[];st.community.profileColor??='blush';st.community.profileGraphic??='star';st.community.profilePhoto??='';st.community.showFollowers??=true;st.community.showFollowing??=true;st.settings??={darkMode:false};st.settings.themeChosen??=false;st.savedItems??=[];}
 function demoNote(){return '<p class="demo-note">Community preview · sample people and stories. Your changes stay on this device.</p>'}
 function button(action,id,label,cls='button secondary'){return `<button type="button" class="${cls}" data-social="${action}" data-id="${esc(id)}">${label}</button>`}
 function cover(p){return p.coverSrc?`<img class="natural-cover" src="${esc(p.coverSrc)}" alt="${esc(p.name)} cover">`:photo(p.image)}
function allPublic(){return [...s().plans.filter(p=>p.visibility==='public').map(p=>({...api.publicPlan(p),author:s().community.name,owner:'me'})),...api.templates.map((p,i)=>({...p,author:people[i].name,owner:people[i].id,publicValues:people[i].values,programTags:[p.category,...people[i].values]}))]}
 function card(p){return `<article class="panel community-plan">${cover(p)}<div class="panel-inner"><span class="tag">${esc(p.category)}</span><h2>${esc(p.name)}</h2><p>${esc(p.intro)}</p><div class="tag-row">${(p.publicValues||[]).map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div><p class="helper">By ${esc(p.author)}</p>${button('public',p.id,'View gameplan')}${p.owner==='me'?'':button('save-plan',p.id,'♡ Save for someday','text-link')}</div></article>`}
 function personCard(p){const followed=s().community.following.includes(p.id);return `<article class="person-card"><div class="avatar" aria-hidden="true">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</div><div><button class="text-link" data-social="person" data-id="${p.id}">${esc(p.name)}</button><small>@${p.handle} · Sample profile</small></div>${button('follow',p.id,followed?'Following':'Follow','follow-button')}</article>`}
 function affirmationCard(set){return `<button class="affirmation-card public-affirmation" data-social="affirmation" data-id="${esc(set.id)}"><span class="affirmation-spark" aria-hidden="true">✦</span><small>Affirmation set · ${esc(set.author)}</small><h2>${esc(set.name)}</h2><p>${esc(set.affirmations[0]||'')}</p><span>${set.affirmations.length} affirmations →</span></button>`}
 function publicAffirmations(){const own=(s().affirmationSets||[]).filter(set=>set.visibility==='public').map(set=>({...set,owner:'me',author:s().community.name}));return [...own,...sampleAffirmations]}
 function openAffirmation(id){const set=publicAffirmations().find(item=>item.id===id);if(!set)return;showDialog(`<span class="eyebrow">PUBLIC AFFIRMATION SET</span><h2>${esc(set.name)}</h2><p class="helper">Shared by ${esc(set.author)}</p><div class="affirmation-reading">${set.affirmations.map((line,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span>${esc(line)}</p>`).join('')}</div>`,true)}
 function boardCard(board){return `<article class="panel public-board-card"><div class="public-board-preview">${(board.items||[]).slice(0,4).map((item,i)=>api.photo(item.image||['travel','gym','study'][i%3])).join('')}</div><div class="panel-inner"><small>Vision board · ${esc(board.author)}</small><h2>${esc(board.name)}</h2><p>${(board.items||[]).length} saved pieces</p></div></article>`}
 function explorePage(){init();return `<div class="page-heading"><div><span class="eyebrow">FIND WHAT MOVES YOU.</span><h1>Explore</h1><p class="subtitle">Search, collect inspiration, and connect with people building their next chapter.</p></div></div><div class="view-tabs explore-tabs" role="tablist">${[['search','Search'],['inspo','Inspo'],['connect','Connect']].map(([v,l])=>`<button type="button" data-explore-tab="${v}" aria-pressed="${exploreTab===v}">${l}</button>`).join('')}</div>${demoNote()}<section class="panel panel-inner explore-search-panel"><label for="explore-search">Search inspiration</label><input id="explore-search" type="search" value="${esc(search)}" placeholder="Search gameplans, boards, affirmations, or images"><details class="browse-filters" open><summary>Filter your search</summary><h3>What do you want to see?</h3><div class="filter-checks">${[['plans','Gameplans'],['affirmations','Affirmations'],['boards','Vision boards'],['images','Images']].map(([v,l])=>`<label class="check-label"><input type="checkbox" data-explore-type value="${v}" ${exploreTypes.includes(v)?'checked':''}>${l}</label>`).join('')}</div><h3>Categories</h3><div class="filter-checks">${categories.map(c=>`<label class="check-label"><input type="checkbox" data-explore-category value="${c}" ${selectedCategories.includes(c)?'checked':''}>${c}</label>`).join('')}</div><h3>Values</h3><div class="filter-checks">${choices.map(c=>`<label class="check-label"><input type="checkbox" data-explore-value value="${c}" ${selectedValues.includes(c)?'checked':''}>${c}</label>`).join('')}</div></details><p id="search-start" class="search-start">Search by a word, category, or value to find inspiration.</p></section><section id="plan-section"><h2 class="section-title">Glow Up Gameplans</h2><div id="plan-results" class="goals-grid"></div></section><section id="affirmation-section"><h2 class="section-title">Words to return to</h2><div id="affirmation-results" class="affirmation-grid public-affirmation-grid"></div></section><section id="board-section"><h2 class="section-title">Vision board inspo</h2><div id="board-results" class="goals-grid"></div></section><section id="image-section"><h2 class="section-title">Images to save</h2><div id="image-results" class="explore-image-grid"></div></section><section id="people-section"><h2 class="section-title">People to connect with</h2><div id="people-results"></div></section>`}
function filterExplore(){const q=search.toLowerCase();selectedCategories=[...document.querySelectorAll('[data-explore-category]:checked')].map(el=>el.value);selectedValues=[...document.querySelectorAll('[data-explore-value]:checked')].map(el=>el.value);exploreTypes=[...document.querySelectorAll('[data-explore-type]:checked')].map(el=>el.value);const has=text=>!q||String(text).toLowerCase().includes(q),matching=p=>(!selectedCategories.length||selectedCategories.includes(p.category))&&(!selectedValues.length||selectedValues.some(v=>(p.publicValues||[]).includes(v)));const plans=allPublic().filter(p=>matching(p)&&has([p.name,p.intro,p.author,...p.publicValues||[],...p.programTags||[]].join(' ')));$('#plan-results').innerHTML=plans.map(card).join('')||'<p class="empty">No gameplans match yet.</p>';$('#people-results').innerHTML=people.filter(p=>has([p.name,p.handle,p.bio,...p.values].join(' '))).map(personCard).join('')||'<p class="helper">No matching people.</p>';$('#affirmation-results').innerHTML=publicAffirmations().filter(set=>has([set.name,set.author,...set.affirmations].join(' '))).map(affirmationCard).join('')||'<p class="empty">No affirmation sets match.</p>';const boards=[...(s().visionBoardMeta?.visibility==='public'?[{...s().visionBoardMeta,items:s().board,author:s().community.name}]:[]),{id:'sample-board',name:'More possibility',author:'Sam Taylor',items:[{image:'travel'},{image:'study'},{image:'home'}]}].filter(board=>has([board.name,board.author].join(' ')));$('#board-results').innerHTML=boards.map(boardCard).join('')||'<p class="empty">No boards match.</p>';const images=[{id:'travel',name:'Open water',image:'travel',category:'Travel',values:['Freedom','Adventure']},{id:'gym',name:'Strong energy',image:'gym',category:'Fitness',values:['Confidence','Health']},{id:'study',name:'Focused space',image:'study',category:'Learning',values:['Curiosity','Growth']},{id:'home',name:'Room to breathe',image:'home',category:'Home',values:['Calm','Balance']}].filter(item=>has([item.name,item.category,...item.values].join(' ')));$('#image-results').innerHTML=images.map(item=>`<article class="explore-image-card">${photo(item.image)}<div><strong>${item.name}</strong><button class="text-link" data-social="save-image" data-id="${item.image}">♡ Save</button></div></article>`).join('');$('.explore-search-panel').hidden=exploreTab!=='search';const searching=Boolean(q||selectedCategories.length||selectedValues.length),visible=exploreTab==='connect'?['people']:exploreTab==='inspo'?['plans','affirmations','boards','images']:searching?exploreTypes:[];const hint=$('#search-start');if(hint)hint.hidden=exploreTab!=='search'||searching;for(const [type,section] of [['people','#people-section'],['plans','#plan-section'],['affirmations','#affirmation-section'],['boards','#board-section'],['images','#image-section']])$(section).hidden=!visible.includes(type)}
function profilePage(){init();const c=s().community,plans=allPublic().filter(p=>p.owner==='me'),affirmations=publicAffirmations().filter(set=>set.owner==='me'),publicBoard=s().visionBoardMeta?.visibility==='public'?{...s().visionBoardMeta,items:s().board,author:c.name}:null,updates=s().community.updates.filter(u=>u.visibility==='public');return `<span class="eyebrow">YOUR SPACE</span><div class="section-head"><h1>My profile</h1>${button('settings','','⚙ Settings','text-link')}</div>${demoNote()}<section class="panel panel-inner profile-header nametag color-${esc(c.profileColor)} graphic-${esc(c.profileGraphic)}"><span class="nametag-graphic"></span>${c.profilePhoto?`<img class="avatar large profile-photo" src="${c.profilePhoto}" alt="${esc(c.name)} profile picture">`:`<div class="avatar large">${esc(c.name[0]||'G')}</div>`}<h2>${esc(c.name)}</h2><p>${esc(c.bio)}</p><div class="profile-counts">${c.showFollowers?button('people-list','followers',`${c.followers.length} Followers`,'text-link'):''}${c.showFollowing?button('people-list','following',`${c.following.length} Following`,'text-link'):''}<span>${plans.length} gameplans</span><span>${affirmations.length} affirmation sets</span></div>${button('edit-profile','','Customize nametag')}</section><h2 class="section-title">Glow Up Gameplans</h2><div class="goals-grid">${plans.map(card).join('')||'<p class="empty">Gameplans you share will appear here.</p>'}</div>${publicBoard?`<h2 class="section-title">Vision Board</h2>${boardCard(publicBoard)}`:''}<h2 class="section-title">Affirmation Sets</h2><div class="affirmation-grid public-affirmation-grid">${affirmations.map(affirmationCard).join('')||'<p class="empty">Affirmation sets you share will appear here.</p>'}</div><div class="section-head section-title"><h2>Journey Updates</h2>${button('update','','＋ Post update')}</div>${updates.map(updateCard).join('')||'<p class="helper">No shared updates yet.</p>'}`}
function updateCard(u){return `<article class="panel panel-inner journey-card"><div class="card-meta"><strong>${esc(u.author||s().community.name)}</strong><span>${esc(u.phase)} · ${u.sample?'Sample story':esc(u.date)}</span></div><h3>${esc(u.title||'My journey')}</h3><p>${esc(u.text)}</p>${u.photo?`<img class="journey-photo" src="${esc(u.photo)}" alt="${esc(u.phase)} journey update">`:''}${u.sampleImage?photo(u.sampleImage):''}<small>${esc(u.planName||'')}</small>${u.sample?'':button('edit-update',u.id,'Edit update','text-link')}</article>`}
 function reviewCard(r){return `<article class="panel panel-inner journey-card"><div class="card-meta"><strong>${esc(r.author||s().community.name)}</strong><span>${r.rating}/5 · ${r.sample?'Sample review':'Your review'}</span></div><p>${esc(r.text)}</p><small>${esc(r.planName||'')}</small></article>`}
 function samples(id){const p=api.templates.find(t=>t.id===id);if(!p)return [];const person=people.find(x=>x.plan===id);return [{id:'sample-before',author:person.name,phase:'Before',title:'Where I started',text:'I had the goal, but needed a routine I could repeat. I chose this plan to give it structure.',sample:true,planName:p.name,sampleImage:p.image},{id:'sample-during',author:'Morgan · sample member',phase:'During',title:'Making it fit my life',text:'The lighter option helped me stay consistent on busy days. I adjusted the schedule to suit my week.',sample:true,planName:p.name},{id:'sample-after',author:person.name,phase:'After',title:'What changed',text:'I finished the plan with a clearer sense of what works for me. My next goal is to keep that rhythm.',sample:true,planName:p.name}]}
 function communitySection(id){const reviews=s().community.reviews.filter(r=>r.planId===id);const updates=s().community.updates.filter(u=>u.publicPlanId===id&&u.visibility==='public');const demo=api.templates.some(t=>t.id===id);return `<section class="community-section"><h2>Journeys & reviews</h2><p class="helper">See how others made this gameplan their own.</p>${demo?'<p class="demo-note">Illustrative sample stories, not actual results or testimonials.</p>':''}<div class="inline-actions">${button('update',id,'＋ Share my journey')}${button('review',id,'Write a review')}</div><label>Show<select id="journey-filter"><option>All updates</option><option>Before</option><option>During</option><option>After</option><option>Reviews</option></select></label><div id="journey-feed">${journeyFeed(id,'All updates')}</div></section>`}
 function journeyFeed(id,phase){const updates=[...s().community.updates.filter(u=>u.publicPlanId===id&&u.visibility==='public'),...samples(id)];const reviews=[...s().community.reviews.filter(r=>r.planId===id),...(api.templates.some(t=>t.id===id)?[{author:'Taylor · sample member',rating:4,text:'A useful starting point. I adjusted the timing and kept the lighter-day option.',sample:true}]:[])];return (phase==='Reviews'?reviews.map(reviewCard):updates.filter(u=>phase==='All updates'||u.phase===phase).map(updateCard)).join('')||'<p class="empty">No updates here yet.</p>'}
 function publicExtras(id){init();const p=allPublic().find(x=>x.id===id);if(!p)return;$('#dialog-content').insertAdjacentHTML('beforeend',`<div class="tag-row">${(p.publicValues||[]).map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div>${button('person',p.owner||'me','View creator profile','text-link')}${videoList(p)}${communitySection(id)}`);$('#journey-filter').onchange=e=>$('#journey-feed').innerHTML=journeyFeed(id,e.target.value);replaceCover(p);}
 function replaceCover(p){if(p.coverSrc){const el=$('.plan-detail-cover');if(el)el.innerHTML=cover(p)}}
 function personalExtras(id){init();const p=s().plans.find(x=>x.id===id);if(!p)return;replaceCover(p);$('#dialog-content').insertAdjacentHTML('beforeend',`<section class="community-section creator-program"><span class="eyebrow">FOR PARTICIPANTS TO FOLLOW</span><h3>Creator-guided program</h3><p class="helper">Add guided lessons to specific days in your program. These are part of the gameplan itself.</p>${button('videos',id,'Manage creator lessons')}${videoList(p)}</section><section class="community-section"><span class="eyebrow">YOUR PARTICIPANT STORY</span><h3>Your journey</h3><p class="helper">Photos and text about your own progress live here.</p><div class="inline-actions">${button('update',id,'＋ Add photo or text update')}</div>${s().community.updates.filter(u=>u.planId===id).map(updateCard).join('')}</section>`)}
function videoList(p){const days=p.programDays||[];if(days.length)return `<section><h3>Program schedule</h3><div class="program-schedule">${days.sort((a,b)=>a.day-b.day).map(d=>`<article class="program-day ${d.type==='rest'?'rest-day':''}"><span class="level-badge">Day ${d.day}</span><div><strong>${esc(d.title||'Rest + reset')}</strong><small>${d.type==='rest'?'Rest day':d.type==='practice'?'Practice day':'Guided lesson'}</small></div>${d.src?`<video controls preload="metadata" playsinline src="${esc(d.src)}"></video>`:''}</article>`).join('')}</div></section>`;return (p.videos||[]).length?`<section><h3>Guided program</h3>${p.videos.map(v=>`<article class="video-item"><strong>Day ${v.day} · ${esc(v.title)}</strong><video controls preload="metadata" playsinline src="${esc(v.src)}"></video></article>`).join('')}</section>`:''}
 function valuesPicker(target){const input=document.getElementById(target);if(!input||input.dataset.picker)return;input.dataset.picker='true';input.insertAdjacentHTML('afterend',`<details class="value-picker"><summary>Choose values ＋</summary><div class="value-choices">${choices.map(v=>`<label class="check-label"><input type="checkbox" value="${v}" ${input.value.split(',').some(x=>x.trim().toLowerCase()===v.toLowerCase())?'checked':''}>${v}</label>`).join('')}</div><label>Other value<input class="other-value" placeholder="Write your own value" maxlength="50"></label><button class="text-link" type="button" data-add-value>Add value</button></details>`);const panel=input.nextElementSibling;panel.addEventListener('change',e=>{if(e.target.type!=='checkbox')return;let vals=input.value.split(',').map(v=>v.trim()).filter(Boolean).filter(v=>v.toLowerCase()!==e.target.value.toLowerCase());if(e.target.checked)vals.push(e.target.value);input.value=vals.join(', ');input.dispatchEvent(new Event('input',{bubbles:true}))});$('[data-add-value]',panel).onclick=()=>{const other=$('.other-value',panel);if(other.value.trim()){input.value=[input.value.trim(),other.value.trim()].filter(Boolean).join(', ');other.value='';input.dispatchEvent(new Event('input',{bubbles:true}))}};}
 function enhancePlan(p){const f=$('#plan-form');if(!f)return;valuesPicker('plan-values');const cat=f.elements.category;for(const c of categories)if(![...cat.options].some(o=>o.value===c))cat.add(new Option(c,c));cat.value=p.category;const horizon=f.elements.horizon;if(![...horizon.options].some(o=>o.value===p.horizon)){horizon.add(new Option(p.horizon,p.horizon));horizon.value=p.horizon}horizon.add(new Option('Custom…','custom'));horizon.parentElement.insertAdjacentHTML('afterend','<label id="custom-horizon-label" hidden>Custom time horizon<input id="custom-horizon" maxlength="60" placeholder="e.g. 10 weeks or by graduation"></label>');horizon.onchange=()=>{$('#custom-horizon-label').hidden=horizon.value!=='custom';$('#custom-horizon').required=horizon.value==='custom'};const coverSelect=f.elements.image;coverSelect.add(new Option('My own image','own'));coverSelect.value=p.coverSrc?'own':p.image;coverSelect.insertAdjacentHTML('afterend',`<label>Upload a cover image<input id="plan-cover-upload" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="helper">Optional. Your photo keeps its natural proportions. Up to 8 MB.</p><div id="cover-preview">${p.coverSrc?cover(p):''}</div>`);let pending=false;$('#plan-cover-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;pending=true;try{p.coverSrc=await readPhoto(file);coverSelect.value='own';$('#cover-preview').innerHTML=cover(p);$('.form-error',f).textContent=''}catch(err){$('.form-error',f).textContent=err.message}finally{pending=false}};f.addEventListener('submit',e=>{if(pending){e.stopImmediatePropagation();e.preventDefault();return api.error(f,'Wait for your image to finish loading.')}if(coverSelect.value==='own'&&!p.coverSrc){e.stopImmediatePropagation();e.preventDefault();return api.error(f,'Upload a cover photo or choose a library image.')}if(horizon.value==='custom'){const value=$('#custom-horizon').value.trim();if(!value){e.preventDefault();e.stopImmediatePropagation();return api.error(f,'Enter your custom time horizon.')}horizon.add(new Option(value,value));horizon.value=value}if(coverSelect.value!=='own')delete p.coverSrc;},true)}
 async function readPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a JPG, PNG or WebP under 8 MB.');return api.resizePhoto(file)}
 function updateForm(id,editId,journalEntry=false){init();const old=s().community.updates.find(u=>u.id===editId);const copies=s().plans;const linked=copies.find(p=>p.id===id||p.sourceId===id);if(id&&!linked&&allPublic().some(p=>p.id===id)){showDialog(`<h2>Start your own journey.</h2><p>Try this gameplan first, then post updates from your copy.</p>${button('try',id,'Try this gameplan')}`);return}if(!copies.length){showDialog('<h2>Start with a gameplan</h2><p>Create or try a gameplan before sharing your journey.</p>');return}const p=old?copies.find(p=>p.id===old.planId):linked||copies[0];let image=old?.photo||'',pending=false;showDialog(`<h2>${old?'Edit your update':journalEntry?'Reflect on your journey.':'Your journey, your words.'}</h2><p class="helper">${journalEntry?'Pause and notice what changed, what helped, and where you want to go next.':'Before, during, or after—capture what’s changing. Posts are device-local previews.'}</p><form id="update-form"><label>Gameplan<select name="plan">${copies.map(x=>`<option value="${x.id}" ${x.id===p?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Journey stage<select name="phase">${['Before','During','After'].map(x=>`<option ${x===old?.phase?'selected':''}>${x}</option>`).join('')}</select></label><label>Title<input name="title" maxlength="100" value="${esc(old?.title)}" placeholder="Where I’m starting"></label><label>Your update<textarea name="text" maxlength="2000" placeholder="What worked, what changed, what’s next?">${esc(old?.text)}</textarea></label><label>Photo (optional)<input id="update-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="update-image-preview">${image?`<img class="journey-photo" src="${image}" alt="Selected update photo">`:''}</div>${button('clear-update-photo','','Remove photo','text-link')}<label>Who can see this?<select name="visibility"><option value="private">Private journal</option><option value="public" ${old?.visibility==='public'?'selected':''}>Public profile · preview</option></select></label><p class="helper">Only updates you mark public appear in your profile and on the source gameplan. Your goal reflections remain private.</p><p class="form-error" role="alert"></p><button class="button">${journalEntry?'Save journey reflection':'Save update'}</button></form>`,true);const f=$('#update-form');$('[data-social="clear-update-photo"]',f).onclick=()=>{image='';$('#update-image-preview').innerHTML='';$('#update-photo').value=''};$('#update-photo').onchange=async e=>{if(!e.target.files[0])return;pending=true;try{image=await readPhoto(e.target.files[0]);$('#update-image-preview').innerHTML=`<img class="journey-photo" src="${image}" alt="Selected update photo">`}catch(err){api.error(f,err.message)}finally{pending=false}};f.onsubmit=async e=>{e.preventDefault();if(pending)return api.error(f,'Wait for your photo to load.');const data=Object.fromEntries(new FormData(f));if(!data.text.trim()&&!image)return api.error(f,'Add some text or a photo.');const plan=copies.find(x=>x.id===data.plan);const u={id:old?.id||uid(),planId:plan.id,publicPlanId:plan.sourceId||plan.id,planName:plan.name,phase:data.phase,title:data.title.trim(),text:data.text.trim(),visibility:data.visibility,photo:image,date:dayKey()};if(old)Object.assign(old,u);else s().community.updates.unshift(u);api.close();api.render();await save(journalEntry?'Journey reflection saved to Diary.':'Journey update saved on this device.')};}
 function reviewForm(id){const copy=s().plans.find(p=>p.sourceId===id);if(!copy){showDialog(`<h2>Try it, then tell your story.</h2><p>Reviews are for gameplans you’ve added to your own plans.</p>${button('try',id,'Try this gameplan')}`);return}const old=s().community.reviews.find(r=>r.planId===id);showDialog(`<h2>How did this gameplan work for you?</h2><form id="review-form"><label>Your rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${n===old?.rating?'selected':''}>${n} out of 5</option>`).join('')}</select></label><label>Your feedback<textarea name="text" required maxlength="2000" placeholder="What helped? What would you change?">${esc(old?.text)}</textarea></label><p class="helper">Public review preview. Saved only on this device.</p><p class="form-error" role="alert"></p><button class="button">Save review</button></form>`);$('#review-form').onsubmit=async e=>{e.preventDefault();const f=e.target;if(!f.elements.text.value.trim())return api.error(f,'Write your feedback first.');const r={id:old?.id||uid(),planId:id,planName:copy.name,rating:Number(f.elements.rating.value),text:f.elements.text.value.trim()};if(old)Object.assign(old,r);else s().community.reviews.unshift(r);await save('Review saved as a preview.');api.publicView(id)}}
function videoForm(id){const p=s().plans.find(p=>p.id===id);if(!p)return;const rows=(p.programDays?.length?p.programDays:[{id:uid(),day:1,type:'lesson',title:'',src:''}]).map(d=>({...d}));const html=()=>rows.map((d,i)=>`<div class="program-day-editor" data-id="${d.id}"><div class="field-pair"><label>Day<input name="program-day" type="number" min="1" max="3650" value="${d.day}"></label><label>Day type<select name="program-type"><option value="lesson" ${d.type==='lesson'?'selected':''}>Video lesson</option><option value="practice" ${d.type==='practice'?'selected':''}>Practice · no video needed</option><option value="rest" ${d.type==='rest'?'selected':''}>Rest day</option></select></label></div><label>Title<input name="program-title" value="${esc(d.title)}" placeholder="${d.type==='rest'?'Rest + reset':'What happens this day?'}"></label><label>Optional video<input name="program-video" type="file" accept="video/mp4,video/webm"></label>${d.src?'<small>Video already attached</small>':''}<button type="button" class="text-link danger" data-remove-program="${d.id}">Remove day</button></div>`).join('');showDialog(`<h2>Creator Studio</h2><p>Build several program days at once. Add lessons, practice days, and intentional rest days.</p><form id="video-form"><label>Search tags, values, and outcomes<input name="programTags" value="${esc((p.programTags||[]).join(', '))}" placeholder="Confidence, strength, beginner, calm"></label><div id="program-rows">${html()}</div><button type="button" class="text-link" id="add-program-day">＋ Add another day</button><p class="helper">A video is optional. Rest and practice days can stand on their own.</p><p class="form-error" role="alert"></p><button class="button">Save program schedule</button></form>${videoList(p)}`,true,'CREATOR STUDIO');const f=$('#video-form');const read=()=>[...f.querySelectorAll('.program-day-editor')].map((row,i)=>({id:row.dataset.id,day:Number($('[name="program-day"]',row).value),type:$('[name="program-type"]',row).value,title:$('[name="program-title"]',row).value.trim(),src:rows.find(x=>x.id===row.dataset.id)?.src||'',file:$('[name="program-video"]',row).files[0]}));$('#add-program-day').onclick=()=>{const next=read();rows.splice(0,rows.length,...next.map(({file,...x})=>x),{id:uid(),day:Math.max(0,...next.map(x=>x.day))+1,type:'lesson',title:'',src:''});$('#program-rows').innerHTML=html()};f.onclick=e=>{const b=e.target.closest('[data-remove-program]');if(!b)return;const next=read().filter(x=>x.id!==b.dataset.removeProgram);rows.splice(0,rows.length,...next.map(({file,...x})=>x));$('#program-rows').innerHTML=html()};f.onsubmit=async e=>{e.preventDefault();const next=read();if(!next.length)return api.error(f,'Add at least one program day.');if(next.some(x=>!x.day||!x.title))return api.error(f,'Give every program day a number and title.');for(const d of next){if(!d.file)continue;if(!['video/mp4','video/webm'].includes(d.file.type)||d.file.size>20*1024*1024)return api.error(f,'Videos must be MP4 or WebM under 20 MB.');d.src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(d.file)})}p.programDays=next.map(({file,...x})=>x);p.programTags=f.elements.programTags.value.split(',').map(x=>x.trim()).filter(Boolean);await save('Creator program saved.');videoForm(id)}}
 function person(id){if(id==='me'){api.close();location.hash='profile';return}const p=people.find(x=>x.id===id);if(!p)return;showDialog(`<span class="eyebrow">SAMPLE PUBLIC PROFILE</span><div class="avatar large">${p.name.split(' ').map(x=>x[0]).join('')}</div><h2>${p.name}</h2><p>@${p.handle}</p><p>${p.bio}</p><div class="tag-row">${p.values.map(v=>`<span class="tag">${v}</span>`).join('')}</div>${button('follow',p.id,s().community.following.includes(p.id)?'Following':'Follow')}<h3 class="section-title">Public affirmation sets</h3><div class="affirmation-grid public-affirmation-grid">${sampleAffirmations.filter(set=>set.owner===p.id).map(affirmationCard).join('')}</div><h3 class="section-title">Public gameplans</h3>${card(allPublic().find(t=>t.id===p.plan))}<h3 class="section-title">Journey updates</h3>${samples(p.plan).filter(u=>u.author===p.name).map(updateCard).join('')}`,true)}
 function peopleList(type){const c=s().community,ids=type==='followers'?c.followers:c.following;showDialog(`<span class="eyebrow">YOUR COMMUNITY</span><h2>${type==='followers'?'Followers':'Following'}</h2>${people.filter(p=>ids.includes(p.id)).map(personCard).join('')||'<p class="empty">No one here yet.</p>'}`)}
function editProfile(){const c=s().community;let photoSrc=c.profilePhoto||'';const colors=[['blush','Blush'],['hotpink','Hot pink'],['rose','Rose'],['cherry','Cherry red'],['peach','Peach'],['sunshine','Sunshine'],['lime','Lime'],['sage','Sage'],['emerald','Emerald'],['aqua','Aqua'],['cobalt','Cobalt'],['lavender','Lavender'],['plum','Plum'],['cream','Cream'],['mocha','Mocha'],['midnight','Midnight']];const graphics=[['star','Chrome star'],['orbit','Orbital ring'],['bolt','Electric bolt'],['heart','Chrome heart'],['butterfly','Butterfly'],['flower','Flower power'],['moon','Moon + stars'],['crown','Crown'],['bow','Bow'],['sparkles','Sparkle cluster'],['none','No graphic']];showDialog(`<h2>Make your nametag yours.</h2><form id="profile-form"><label>Profile picture<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="profile-photo-preview">${photoSrc?`<img class="avatar large profile-photo" src="${photoSrc}" alt="Profile preview">`:''}</div><label>Display name<input name="name" required maxlength="50" value="${esc(c.name)}"></label><label>Bio<textarea name="bio" maxlength="250">${esc(c.bio)}</textarea></label><div class="field-pair"><label>Nametag color<select name="profileColor">${colors.map(([v,l])=>`<option value="${v}" ${c.profileColor===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Graphic<select name="profileGraphic">${graphics.map(([v,l])=>`<option value="${v}" ${c.profileGraphic===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="form-error"></p><button class="button">Save profile</button></form>`,false,'YOUR NAMETAG');const f=$('#profile-form');$('#profile-photo').onchange=async e=>{try{photoSrc=await readPhoto(e.target.files[0]);$('#profile-photo-preview').innerHTML=`<img class="avatar large profile-photo" src="${photoSrc}" alt="Profile preview">`}catch(err){api.error(f,err.message)}};f.onsubmit=async e=>{e.preventDefault();if(!f.elements.name.value.trim())return api.error(f,'Enter a display name.');c.name=f.elements.name.value.trim();c.bio=f.elements.bio.value.trim();c.profileColor=f.elements.profileColor.value;c.profileGraphic=f.elements.profileGraphic.value;c.profilePhoto=photoSrc;api.close();api.render();await save('Profile saved.')}}function settingsForm(){const c=s().community,settings=s().settings;showDialog(`<h2>Settings</h2><form id="settings-form"><section class="settings-group"><span class="eyebrow">APPEARANCE</span><fieldset class="theme-switch" aria-label="Color mode"><label><input type="radio" name="appearance" value="light" ${!settings.darkMode?'checked':''}><span>Light mode</span></label><label><input type="radio" name="appearance" value="dark" ${settings.darkMode?'checked':''}><span>Dark mode</span></label></fieldset><small class="theme-setting-note">Choose how Glow Getters looks on this device.</small></section><section class="settings-group"><span class="eyebrow">PRIVACY</span><label class="setting-row"><span><strong>Show followers</strong><small>Let people open your followers list.</small></span><input type="checkbox" name="showFollowers" ${c.showFollowers?'checked':''}></label><label class="setting-row"><span><strong>Show following</strong><small>Let people open your following list.</small></span><input type="checkbox" name="showFollowing" ${c.showFollowing?'checked':''}></label></section><button class="button">Save settings</button></form>`,false,'SETTINGS');$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=e.target;settings.darkMode=f.elements.appearance.value==='dark';settings.themeChosen=true;c.showFollowers=f.elements.showFollowers.checked;c.showFollowing=f.elements.showFollowing.checked;api.close();api.render();await save('Settings saved.')}}
function drawer(){const el=$('#space-drawer');el.hidden=false;el.querySelector('a').focus();$('#dock-space').setAttribute('aria-expanded','true')}
 function closeDrawer(){const el=$('#space-drawer');if(el)el.hidden=true;$('#dock-space')?.setAttribute('aria-expanded','false')}
function decorate(){init();if(!$('#mobile-dock')){document.body.insertAdjacentHTML('beforeend',`<nav id="mobile-dock" aria-label="Mobile dock"><a href="#today"><span>⌂</span>Today</a><button id="dock-space" aria-expanded="false"><span>▦</span>My Space</button><a href="#explore"><span>⌕</span>Explore</a><a href="#profile"><span>◎</span>Profile</a></nav><div id="space-drawer" hidden><button class="drawer-scrim" aria-label="Close My Space"></button><aside class="space-panel"><div class="section-head"><h2>My Space</h2><button class="icon-btn" id="close-space">×</button></div><p>Choose where you want to go.</p><nav><a href="#overview">Goals</a><a href="#goals">Plans</a><a class="space-vision-link" href="#vision">Vision</a><a href="#diary">Reflections</a><a href="#saved">Saved</a></nav></aside></div>`);$('#dock-space').onclick=()=>{api.close();$('#space-drawer').hidden?drawer():closeDrawer()};$('.drawer-scrim').onclick=closeDrawer;$('#close-space').onclick=closeDrawer;$('#space-drawer').addEventListener('click',e=>{if(e.target.closest('a'))closeDrawer()});$('#mobile-dock').addEventListener('click',e=>{if(e.target.closest('a')){api.close();closeDrawer()}})}const route=location.hash.slice(1)||'today';for(const el of $('#mobile-dock').children)el.classList.toggle('active',el.id==='dock-space'?['overview','goals','lifestyle','vision','reflect','diary','saved'].includes(route):el.getAttribute('href')==='#'+route);if(route==='reflect')valuesPicker('growth-values');if(route==='explore'){document.querySelectorAll('[data-explore-tab]').forEach(tab=>tab.onclick=()=>{exploreTab=tab.dataset.exploreTab;api.render()});filterExplore();$('#explore-search').oninput=e=>{search=e.target.value;filterExplore()};document.querySelectorAll('[data-explore-type],[data-explore-category],[data-explore-value]').forEach(box=>box.onchange=filterExplore)}if(route==='vision')bindDrag()}
function bindDrag(){const board=$('.board-editing');if(!board)return;[...board.querySelectorAll('.board-tile')].forEach(tile=>{const id=tile.dataset.boardId,handle=$('.drag-handle',tile);if(!id||!handle)return;let startX=0,startY=0,originX=0,originY=0;handle.onpointerdown=e=>{e.preventDefault();const item=s().board.find(x=>x.id===id);startX=e.clientX;startY=e.clientY;originX=Number(item.x)||0;originY=Number(item.y)||0;item.z=Math.max(1,...s().board.map(x=>Number(x.z)||1))+1;tile.style.setProperty('--z',(item.kind==='text'||item.kind==='affirmation'?100:item.kind==='graphic'?60:0)+item.z);tile.classList.add('dragging');handle.setPointerCapture(e.pointerId)};handle.onpointermove=e=>{if(!handle.hasPointerCapture(e.pointerId))return;const item=s().board.find(x=>x.id===id),r=board.getBoundingClientRect();item.x=Math.max(-5,Math.min(88,originX+(e.clientX-startX)/r.width*100));item.y=Math.max(0,Math.min(92,originY+(e.clientY-startY)/r.height*100));tile.style.setProperty('--x',item.x);tile.style.setProperty('--y',item.y)};handle.onpointerup=async e=>{tile.classList.remove('dragging');try{handle.releasePointerCapture(e.pointerId)}catch{}await save('Collage position saved.')}})}
 async function reorder(from,to){const a=s().board.findIndex(v=>v.id===from),b=s().board.findIndex(v=>v.id===to);if(a<0||b<0||a===b)return;const [item]=s().board.splice(a,1);s().board.splice(b,0,item);api.render();await save('Vision board rearranged.')}
 function sharingExtras(id){const p=s().plans.find(p=>p.id===id),f=$('#share-form');if(!p||!f)return;f.insertAdjacentHTML('afterbegin',`<label>Public discovery values<input id="public-values" value="${esc((p.publicValues||[]).join(', '))}" placeholder="Choose values you want to share"></label><p class="helper">Optional tags for Explore. These are separate from your private reflections.</p>`);valuesPicker('public-values');f.addEventListener('submit',()=>{p.publicValues=$('#public-values').value.split(',').map(v=>v.trim()).filter(Boolean)},true)}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-social]');if(!b)return;init();const id=b.dataset.id;switch(b.dataset.social){case'public':api.publicView(id);break;case'person':person(id);break;case'save-plan':s().savedPlans??=[];if(!s().savedPlans.includes(id))s().savedPlans.push(id);await save('Plan saved for someday.');toast('Saved plans will be waiting in Gameplans.');break;case'people-list':peopleList(id);break;case'save-image':{const meta={travel:['Open water','Travel',['Freedom','Adventure']],gym:['Strong energy','Fitness',['Confidence','Health']],study:['Focused space','Learning',['Curiosity','Growth']],home:['Room to breathe','Home',['Calm','Balance']]}[id];s().savedItems.push({id:uid(),type:'image',image:id,name:meta[0],category:meta[1],values:meta[2],detail:'Saved from Explore'});await save('Image saved to Saved.');toast('Saved. Add it to a board whenever you are ready.');break}case'affirmation':openAffirmation(id);break;case'follow':{const list=s().community.following,at=list.indexOf(id);if(at>=0)list.splice(at,1);else list.push(id);b.textContent=at>=0?'Follow':'Following';await save('Following preference saved in this preview.');if(location.hash==='#profile')api.render();break}case'edit-profile':editProfile();break;case'settings':settingsForm();break;case'update':updateForm(id);break;case'edit-update':updateForm('',id);break;case'review':reviewForm(id);break;case'videos':videoForm(id);break;case'try':await api.copyPlan(id);break}});
 return {init,decorate,enhancePlan,publicExtras,personalExtras,sharingExtras,cover,explorePage,profilePage,journeyForm:()=>updateForm('','',true)};
}

